SOURCES=[{"url":"https://www.yacjh.kh.edu.tw/upload/221/101_30637/114%E4%B8%8B%E5%AD%B8%E6%9C%9F%E7%AC%AC%E4%B8%80%E6%AC%A1%E6%AE%B5%E8%80%83%E4%B8%89%E5%B9%B4%E7%B4%9A%E7%9A%84%E7%A4%BE%E6%9C%83.pdf","title":"高雄市立鹽埕國民中學公開段考社會科；僅研究制度、政治變遷與資料判讀題型，未複製原題。","year":"114","locator":"公開段考社會科 PDF；第 1 題至第 10 題型範圍：制度、時序與因果界線","observedPattern":"由制度文本、地方材料與群體行動要求學生分析政治變化與證據範圍。"},{"url":"https://affairs.kh.edu.tw/1126/upload/file_list/149","title":"高雄市立文府國民中學公開社會科試題入口；僅研究多資料互證題型，未複製原題。","year":"113-114","locator":"公開試題與解答入口；第 1 題至第 10 題型範圍：制度、政治變遷與多重證據","observedPattern":"比較法令、地方記錄與群體觀點，區分直接記錄、推論與待補證主張。"},{"url":"https://www.dwm.kh.edu.tw/view/index.php?MainMenuId=64182&MainType=0&SubMenuId=64184&SubType=104&WebID=344","title":"高雄市立大灣國民中學公開段考試題入口；僅研究政治制度與多方角色題型，未複製原題。","year":"113-114","locator":"公開段考試題入口；第 1 題至第 10 題型範圍：政治回應、社會變遷與多方角色","observedPattern":"從歷史材料分析制度、利益與生活變化，不以單一來源包辦結論。"}]
